package com.termex.replay15.editor

import com.termex.replay15.editor.assets.BuiltInEffectPresets
import com.termex.replay15.editor.assets.EffectCost
import com.termex.replay15.editor.assets.EffectDefinition
import com.termex.replay15.editor.assets.EffectEngine
import com.termex.replay15.editor.assets.EffectPreset
import java.io.File
import org.json.JSONArray
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/** Guards the shipped preset library (generated by tools/library/gen_effect_presets.py). */
class EffectPresetLibraryTest {
    private fun assets(relative: String): File =
        sequenceOf(File("src/main/assets/editor/$relative"), File("editor-engine/src/main/assets/editor/$relative"))
            .firstOrNull { it.exists() } ?: error("missing assets/editor/$relative")

    private val presets: List<EffectPreset> by lazy { BuiltInEffectPresets.parse(assets("effect_presets.json").readText()) }
    private val definitions: Map<String, EffectDefinition> by lazy {
        val array = JSONArray(assets("effects.json").readText())
        List(array.length()) { EffectDefinition.parse(array.getJSONObject(it).toString()) }.associateBy { it.id }
    }

    @Test
    fun `library ships 300 presets with unique ids and names`() {
        assertTrue("Expected 300+ presets, found ${presets.size}", presets.size >= 300)
        assertEquals("Duplicate preset ids", presets.size, presets.map { it.id }.distinct().size)
        assertEquals("Duplicate preset names", presets.size, presets.map { it.name.lowercase() }.distinct().size)
    }

    @Test
    fun `the original presets keep their ids and order`() {
        val original = listOf(
            "cyber_signal", "impact_combo", "soft_dream", "broken_tape", "neon_arcade", "liquid_lens", "clean_film", "film_35mm",
            "vintage_film", "dark_cinema", "warm_cinema", "cold_cinema", "kill_impact", "headshot", "damage", "explosion",
            "speed", "beat_zoom", "victory", "film_look",
        )
        assertEquals(original, presets.take(original.size).map { it.id })
    }

    @Test
    fun `every node uses a shipped effect and stays inside its parameter ranges`() {
        for (preset in presets) for (node in preset.nodes) {
            val definition = definitions[node.assetId] ?: error("${preset.id}: unknown effect ${node.assetId}")
            assertEquals("${preset.id}/${node.assetId} version", definition.version, node.version)
            for ((key, value) in node.values) {
                val parameter = definition.parameters.firstOrNull { it.id == key }
                    ?: error("${preset.id}/${node.assetId}: unknown parameter $key")
                assertTrue("${preset.id}/${node.assetId}.$key=$value outside ${parameter.min}..${parameter.max}", value in parameter.min..parameter.max)
            }
        }
    }

    @Test
    fun `new presets stay light enough for realtime preview and the 12 effect stack`() {
        val originalFilmLook = "film_look" // shipped before these limits existed, with 6 nodes
        for (preset in presets.filter { it.id != originalFilmLook }) {
            val nodes = preset.nodes.map { definitions.getValue(it.assetId) }
            assertTrue("${preset.id} has ${nodes.size} nodes", nodes.size <= 5)
            assertTrue("${preset.id} stacks ${nodes.count { it.cost == EffectCost.MEDIUM }} MEDIUM effects", nodes.count { it.cost == EffectCost.MEDIUM } <= 3)
            assertTrue("${preset.id} stacks temporal effects", nodes.count { it.temporal || it.engine == EffectEngine.TEMPORAL_TRAIL } <= 2)
        }
    }

    @Test
    fun `every shipped effect appears in at least one preset`() {
        val used = presets.flatMap { it.nodes }.map { it.assetId }.toSet()
        val missing = definitions.keys - used
        assertTrue("${missing.size} effects have no preset: ${missing.take(10)}", missing.isEmpty())
    }

    @Test
    fun `gallery tabs keep the historical order first and list every category`() {
        val tabs = BuiltInEffectPresets.orderedCategories(presets)
        assertEquals(listOf("Cinema", "Film", "Gaming", "Retro", "Distorsao"), tabs.take(5))
        assertEquals(presets.map { it.category }.toSet(), tabs.toSet())
        assertEquals("Tabs must not repeat", tabs.size, tabs.distinct().size)
    }
}
